{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFile } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { extname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('.', import.meta.url));
const db = new DatabaseSync(process.env.DB_PATH || join(root, 'workboard.sqlite'));
db.exec(`
  PRAGMA journal_mode = WAL;
  CREATE TABLE IF NOT EXISTS projects (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    created_at INTEGER NOT NULL,
    archived INTEGER NOT NULL DEFAULT 0
    ,default_priority TEXT NOT NULL DEFAULT 'Normal'
  );
  CREATE TABLE IF NOT EXISTS tasks (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0,
    priority TEXT NOT NULL DEFAULT 'Normal',
    due_date TEXT,
    created_at INTEGER NOT NULL
  );
`);
// Upgrade databases created by earlier checkpoints without disturbing their data.
const projectColumns = db.prepare('PRAGMA table_info(projects)').all().map(column => column.name);
if (!projectColumns.includes('archived')) db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0');
if (!projectColumns.includes('default_priority')) db.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal'");
const taskColumns = db.prepare('PRAGMA table_info(tasks)').all().map(column => column.name);
if (!taskColumns.includes('priority')) db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal'");
if (!taskColumns.includes('due_date')) db.exec('ALTER TABLE tasks ADD COLUMN due_date TEXT');
const listProjects = db.prepare(`SELECT p.id, p.name, p.archived, p.default_priority AS defaultPriority,
  COUNT(t.id) AS totalCount, COALESCE(SUM(t.completed), 0) AS completedCount
  FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
  GROUP BY p.id ORDER BY p.created_at, p.rowid`);
const findProject = db.prepare('SELECT id, name, archived, default_priority AS defaultPriority FROM projects WHERE id = ?');
const insertProject = db.prepare('INSERT INTO projects (id, name, created_at) VALUES (?, ?, ?)');
const listTasks = db.prepare('SELECT id, project_id AS projectId, title, completed, priority, due_date AS dueDate FROM tasks WHERE project_id = ? ORDER BY created_at, rowid');
const insertTask = db.prepare('INSERT INTO tasks (id, project_id, title, completed, created_at) VALUES (?, ?, ?, 0, ?)');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
const findTask = db.prepare('SELECT id, project_id AS projectId, title, completed, priority, due_date AS dueDate FROM tasks WHERE id = ? AND project_id = ?');
const updateTaskTitle = db.prepare('UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?');
const updateTaskPriority = db.prepare('UPDATE tasks SET priority = ? WHERE id = ? AND project_id = ?');
const updateTaskDueDate = db.prepare('UPDATE tasks SET due_date = ? WHERE id = ? AND project_id = ?');
const updateProjectArchived = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const updateProjectName = db.prepare('UPDATE projects SET name = ? WHERE id = ?');
const updateProjectDefaultPriority = db.prepare('UPDATE projects SET default_priority = ? WHERE id = ?');

const mimeTypes = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8' };
const server = createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  if (req.method === 'GET' && url.pathname === '/health') {
    res.writeHead(200, { 'content-type': 'application/json; charset=utf-8' });
    res.end(JSON.stringify({ status: 'ok' }));
    return;
  }
  if (url.pathname === '/api/projects' && req.method === 'GET') {
    return json(res, 200, listProjects.all().map(project => ({ ...project, archived: Boolean(project.archived) })));
  }
  if (url.pathname === '/api/projects' && req.method === 'POST') {
    try {
      const body = await readJson(req);
      const name = typeof body.name === 'string' ? body.name.trim() : '';
      if (!name) return json(res, 400, { error: 'Project name is required' });
      const project = { id: randomUUID(), name, archived: false };
      insertProject.run(project.id, project.name, Date.now());
      return json(res, 201, project);
    } catch {
      return json(res, 400, { error: 'Invalid request' });
    }
  }
  const archiveMatch = url.pathname.match(/^\/api\/projects\/([^/]+)\/archive$/);
  if (req.method === 'PATCH' && archiveMatch) {
    const projectId = decodeURIComponent(archiveMatch[1]);
    if (!findProject.get(projectId)) return json(res, 404, { error: 'Project not found' });
    try {
      const body = await readJson(req);
      if (typeof body.archived !== 'boolean') return json(res, 400, { error: 'Invalid archive state' });
      updateProjectArchived.run(body.archived ? 1 : 0, projectId);
      return json(res, 200, { id: projectId, archived: body.archived });
    } catch { return json(res, 400, { error: 'Invalid request' }); }
  }
  const renameMatch = url.pathname.match(/^\/api\/projects\/([^/]+)\/rename$/);
  if (req.method === 'PATCH' && renameMatch) {
    const projectId = decodeURIComponent(renameMatch[1]);
    const project = findProject.get(projectId);
    if (!project) return json(res, 404, { error: 'Project not found' });
    if (project.archived) return json(res, 409, { error: 'Archived projects cannot be renamed' });
    try {
      const body = await readJson(req);
      const name = typeof body.name === 'string' ? body.name.trim() : '';
      if (!name) return json(res, 400, { error: 'Project name is required' });
      updateProjectName.run(name, projectId);
      return json(res, 200, { id: projectId, name, archived: false });
    } catch { return json(res, 400, { error: 'Invalid request' }); }
  }
  const defaultPriorityMatch = url.pathname.match(/^\/api\/projects\/([^/]+)\/default-priority$/);
  if (req.method === 'PATCH' && defaultPriorityMatch) {
    const projectId = decodeURIComponent(defaultPriorityMatch[1]);
    const project = findProject.get(projectId);
    if (!project) return json(res, 404, { error: 'Project not found' });
    if (project.archived) return json(res, 409, { error: 'Archived projects cannot be changed' });
    try {
      const body = await readJson(req);
      if (!['Low', 'Normal', 'High'].includes(body.priority)) return json(res, 400, { error: 'Invalid task priority' });
      updateProjectDefaultPriority.run(body.priority, projectId);
      return json(res, 200, { ...project, defaultPriority: body.priority, archived: false });
    } catch { return json(res, 400, { error: 'Invalid request' }); }
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/([^/]+)$/);
  if (req.method === 'GET' && projectMatch) {
    const project = findProject.get(decodeURIComponent(projectMatch[1]));
    return project ? json(res, 200, { ...project, archived: Boolean(project.archived) }) : json(res, 404, { error: 'Project not found' });
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/([^/]+)\/tasks$/);
  if (tasksMatch) {
    const projectId = decodeURIComponent(tasksMatch[1]);
    const project = findProject.get(projectId);
    if (!project) return json(res, 404, { error: 'Project not found' });
    if (req.method === 'GET') return json(res, 200, listTasks.all(projectId).map(task => ({ ...task, completed: Boolean(task.completed) })));
    if (req.method === 'POST') {
      if (project.archived) return json(res, 409, { error: 'Archived projects cannot accept tasks' });
      try {
        const body = await readJson(req);
        const title = typeof body.title === 'string' ? body.title.trim() : '';
        if (!title) return json(res, 400, { error: 'Task title is required' });
        const task = { id: randomUUID(), projectId, title, completed: false, priority: project.defaultPriority };
        db.prepare('INSERT INTO tasks (id, project_id, title, completed, priority, created_at) VALUES (?, ?, ?, 0, ?, ?)').run(task.id, projectId, title, task.priority, Date.now());
        return json(res, 201, task);
      } catch { return json(res, 400, { error: 'Invalid request' }); }
    }
  }
  const moveMatch = url.pathname.match(/^\/api\/projects\/([^/]+)\/tasks\/([^/]+)\/move$/);
  if (req.method === 'POST' && moveMatch) {
    const sourceId = decodeURIComponent(moveMatch[1]);
    const taskId = decodeURIComponent(moveMatch[2]);
    const source = findProject.get(sourceId);
    if (!source) return json(res, 404, { error: 'Project not found' });
    if (source.archived) return json(res, 409, { error: 'Archived projects cannot move tasks' });
    try {
      const body = await readJson(req);
      const destinationId = typeof body.destinationProjectId === 'string' ? body.destinationProjectId : '';
      const destination = findProject.get(destinationId);
      if (!destination || destination.archived || destinationId === sourceId) return json(res, 400, { error: 'Invalid destination project' });
      const task = findTask.get(taskId, sourceId);
      if (!task) return json(res, 404, { error: 'Task not found' });
      const nextOrder = db.prepare('SELECT COALESCE(MAX(created_at), 0) + 1 AS value FROM tasks WHERE project_id = ?').get(destinationId).value;
      const result = db.prepare('UPDATE tasks SET project_id = ?, created_at = ? WHERE id = ? AND project_id = ?').run(destinationId, nextOrder, taskId, sourceId);
      if (!Number(result.changes)) return json(res, 404, { error: 'Task not found' });
      return json(res, 200, { ...task, projectId: destinationId });
    } catch { return json(res, 400, { error: 'Invalid request' }); }
  }
  const taskMatch = url.pathname.match(/^\/api\/projects\/([^/]+)\/tasks\/([^/]+)$/);
  if (req.method === 'PATCH' && taskMatch) {
    const projectId = decodeURIComponent(taskMatch[1]);
    const taskId = decodeURIComponent(taskMatch[2]);
    const project = findProject.get(projectId);
    if (!project) return json(res, 404, { error: 'Project not found' });
    if (project.archived) return json(res, 409, { error: 'Archived project tasks cannot be changed' });
    try {
      const body = await readJson(req);
      if (typeof body.title === 'string') {
        const title = body.title.trim();
        if (!title) return json(res, 400, { error: 'Task title is required' });
        const result = updateTaskTitle.run(title, taskId, projectId);
        if (!Number(result.changes)) return json(res, 404, { error: 'Task not found' });
        const task = findTask.get(taskId, projectId);
        return json(res, 200, { ...task, completed: Boolean(task.completed) });
      }
      if (typeof body.priority === 'string') {
        if (!['Low', 'Normal', 'High'].includes(body.priority)) return json(res, 400, { error: 'Invalid task priority' });
        const result = updateTaskPriority.run(body.priority, taskId, projectId);
        if (!Number(result.changes)) return json(res, 404, { error: 'Task not found' });
        const task = findTask.get(taskId, projectId);
        return json(res, 200, { ...task, completed: Boolean(task.completed), priority: body.priority });
      }
      if (typeof body.dueDate === 'string') {
        const trimmed = body.dueDate.trim();
        const dueDate = trimmed === '' ? null : trimmed;
        if (dueDate !== null && !isValidDate(dueDate)) return json(res, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
        const result = updateTaskDueDate.run(dueDate, taskId, projectId);
        if (!Number(result.changes)) return json(res, 404, { error: 'Task not found' });
        const task = findTask.get(taskId, projectId);
        return json(res, 200, { ...task, completed: Boolean(task.completed) });
      }
      if (typeof body.completed !== 'boolean') return json(res, 400, { error: 'Invalid completion state' });
      const result = updateTask.run(body.completed ? 1 : 0, taskId, projectId);
      if (!Number(result.changes)) return json(res, 404, { error: 'Task not found' });
      return json(res, 200, { id: taskId, projectId, completed: body.completed });
    } catch { return json(res, 400, { error: 'Invalid request' }); }
  }
  if (req.method === 'GET' && (url.pathname === '/' || url.pathname.startsWith('/projects/'))) {
    return serveFile(res, 'index.html');
  }
  if (req.method === 'GET' && url.pathname.startsWith('/')) {
    const name = url.pathname.slice(1);
    if (name && !name.includes('..') && !name.includes('/')) return serveFile(res, name);
  }
  res.writeHead(404, { 'content-type': 'text/plain; charset=utf-8' });
  res.end('Not found');
});

function json(res, status, data) {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(data));
}

async function readJson(req) {
  let raw = '';
  for await (const chunk of req) raw += chunk;
  return JSON.parse(raw || '{}');
}

function isValidDate(value) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) return false;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  if (year < 1 || month < 1 || month > 12 || day < 1) return false;
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day <= daysInMonth[month - 1];
}

async function serveFile(res, name) {
  try {
    const body = await readFile(join(root, 'public', name));
    res.writeHead(200, { 'content-type': mimeTypes[extname(name)] || 'application/octet-stream' });
    res.end(body);
  } catch {
    res.writeHead(404);
    res.end('Not found');
  }
}

const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0');
const listView = document.querySelector('#project-list');
const detailView = document.querySelector('#project-detail');
const projectsNode = document.querySelector('#projects');
const alertNode = document.querySelector('#form-alert');
const form = document.querySelector('#create-form');
const nameInput = document.querySelector('#project-name');
const taskForm = document.querySelector('#task-form');
const taskInput = document.querySelector('#task-title');
const taskAlert = document.querySelector('#task-alert');
const tasksNode = document.querySelector('#tasks');
const taskFilter = document.querySelector('#task-filter');
const priorityFilter = document.querySelector('#priority-filter');
const dueRangeForm = document.querySelector('#due-range-form');
const dueFromInput = document.querySelector('#due-from');
const dueThroughInput = document.querySelector('#due-through');
const projectFilter = document.querySelector('#project-filter');
const renameForm = document.querySelector('#rename-form');
const renameInput = document.querySelector('#new-project-name');
const renameAlert = document.querySelector('#rename-alert');
const defaultPriority = document.querySelector('#default-priority');
let activeProjectId = null;
let currentTasks = [];
let activeProjects = [];
let activeProjectArchived = false;
let appliedDueFrom = '';
let appliedDueThrough = '';

async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Something went wrong');
  return data;
}

function showList() {
  listView.hidden = false;
  detailView.hidden = true;
  history.pushState({}, '', '/');
  loadProjects();
}

async function loadProjects() {
  const projects = await request('/api/projects');
  projectsNode.replaceChildren();
  const visibleProjects = projects.filter(project => project.archived === (projectFilter.value === 'Archived'));
  document.querySelector('#project-count').textContent = visibleProjects.length ? String(visibleProjects.length).padStart(2, '0') : '';
  if (!visibleProjects.length) {
    const empty = document.createElement('div');
    empty.className = 'empty-state';
    empty.innerHTML = `<span class="empty-icon" aria-hidden="true">◇</span><strong>No ${projectFilter.value.toLowerCase()} projects</strong><span>${projectFilter.value === 'Active' ? 'Create your first project to get started.' : 'Archived projects will appear here.'}</span>`;
    projectsNode.append(empty);
    return;
  }
  for (const project of visibleProjects) {
    const row = document.createElement('div');
    row.className = 'project-row';
    row.dataset.testid = 'project-row';
    const name = document.createElement('span');
    name.className = 'project-name';
    name.textContent = project.name;
    const summary = document.createElement('span');
    summary.className = 'project-summary';
    summary.dataset.testid = 'project-summary';
    summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
    const button = document.createElement('button');
    button.className = 'open-button';
    button.type = 'button';
    button.textContent = 'Open project';
    button.addEventListener('click', () => openProject(project.id));
    const actions = document.createElement('div');
    actions.className = 'project-actions';
    const archiveButton = document.createElement('button');
    archiveButton.className = 'open-button';
    archiveButton.type = 'button';
    archiveButton.textContent = project.archived ? 'Restore project' : 'Archive project';
    archiveButton.addEventListener('click', async () => {
      await request(`/api/projects/${encodeURIComponent(project.id)}/archive`, {
        method: 'PATCH', headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived })
      });
      await loadProjects();
    });
    actions.append(button, archiveButton);
    row.append(name, summary, actions);
    projectsNode.append(row);
  }
}

async function openProject(id) {
  const project = await request(`/api/projects/${encodeURIComponent(id)}`);
  taskFilter.value = 'All';
  priorityFilter.value = 'All';
  resetDueRange();
  document.querySelector('#detail-name').textContent = project.name;
  activeProjectId = project.id;
  setProjectArchived(project.archived);
  defaultPriority.value = project.defaultPriority || 'Normal';
  defaultPriority.dataset.saved = defaultPriority.value;
  listView.hidden = true;
  detailView.hidden = false;
  history.pushState({}, '', `/projects/${encodeURIComponent(project.id)}`);
  await loadTasks();
}

function setProjectArchived(archived) {
  activeProjectArchived = archived;
  document.querySelector('#archived-label').hidden = !archived;
  taskInput.disabled = archived;
  taskForm.querySelector('button[type="submit"]').disabled = archived;
  taskForm.setAttribute('aria-disabled', String(archived));
  renameInput.disabled = archived;
  renameForm.querySelector('button[type="submit"]').disabled = archived;
  defaultPriority.disabled = archived;
}

function drawTasks() {
  tasksNode.replaceChildren();
  const filter = taskFilter.value;
  const selectedPriority = priorityFilter.value;
  const visible = currentTasks.filter(task =>
    (filter === 'All' || (filter === 'Open' ? !task.completed : task.completed)) &&
    (selectedPriority === 'All' || (task.priority || 'Normal') === selectedPriority) &&
    (!appliedDueFrom && !appliedDueThrough || Boolean(task.dueDate)) &&
    (!appliedDueFrom || (task.dueDate || '') >= appliedDueFrom) &&
    (!appliedDueThrough || (task.dueDate || '') <= appliedDueThrough)
  );
  if (!visible.length) {
    const empty = document.createElement('div');
    empty.className = 'task-empty';
    empty.textContent = currentTasks.length ? 'No tasks match this filter.' : 'No tasks yet.';
    tasksNode.append(empty);
  }
  for (const task of visible) {
    const row = document.createElement('div');
    row.className = 'task-row';
    row.dataset.testid = 'task-row';
    const title = document.createElement('span');
    title.className = 'task-title';
    title.textContent = task.title;
    const label = document.createElement('label');
    label.className = 'task-check';
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = task.completed;
    checkbox.disabled = activeProjectArchived;
    checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    checkbox.addEventListener('change', async () => {
      try {
        await request(`/api/projects/${encodeURIComponent(activeProjectId)}/tasks/${encodeURIComponent(task.id)}`, {
          method: 'PATCH', headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ completed: checkbox.checked })
        });
        task.completed = checkbox.checked;
        drawTasks();
      } catch { checkbox.checked = task.completed; }
    });
    const renameForm = document.createElement('form');
    renameForm.className = 'task-rename-form';
    const renameInput = document.createElement('input');
    renameInput.type = 'text';
    renameInput.value = task.title;
    renameInput.setAttribute('aria-label', 'New task title');
    renameInput.disabled = activeProjectArchived;
    const renameButton = document.createElement('button');
    renameButton.type = 'submit';
    renameButton.className = 'open-button';
    renameButton.textContent = 'Rename task';
    renameButton.disabled = activeProjectArchived;
    renameForm.addEventListener('submit', async event => {
      event.preventDefault();
      try {
        const renamed = await request(`/api/projects/${encodeURIComponent(activeProjectId)}/tasks/${encodeURIComponent(task.id)}`, {
          method: 'PATCH', headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ title: renameInput.value })
        });
        task.title = renamed.title;
        drawTasks();
      } catch (error) {
        taskAlert.textContent = error.message;
        taskAlert.hidden = false;
      }
    });
    renameForm.append(renameInput, renameButton);
    const priority = document.createElement('select');
    priority.setAttribute('aria-label', 'Task priority');
    for (const value of ['Low', 'Normal', 'High']) {
      const option = document.createElement('option');
      option.value = value;
      option.textContent = value;
      priority.append(option);
    }
    priority.value = task.priority || 'Normal';
    priority.disabled = activeProjectArchived;
    priority.addEventListener('change', async () => {
      const previous = task.priority || 'Normal';
      try {
        const updated = await request(`/api/projects/${encodeURIComponent(activeProjectId)}/tasks/${encodeURIComponent(task.id)}`, {
          method: 'PATCH', headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ priority: priority.value })
        });
        task.priority = updated.priority;
        drawTasks();
      } catch (error) {
        priority.value = previous;
        taskAlert.textContent = error.message;
        taskAlert.hidden = false;
      }
    });
    const dueDateForm = document.createElement('form');
    dueDateForm.className = 'task-due-date-form';
    const dueDateInput = document.createElement('input');
    dueDateInput.type = 'text';
    dueDateInput.value = task.dueDate || '';
    dueDateInput.setAttribute('aria-label', 'Task due date');
    dueDateInput.disabled = activeProjectArchived;
    const saveDueDate = document.createElement('button');
    saveDueDate.type = 'submit';
    saveDueDate.className = 'open-button';
    saveDueDate.textContent = 'Save due date';
    saveDueDate.disabled = activeProjectArchived;
    dueDateForm.addEventListener('submit', async event => {
      event.preventDefault();
      try {
        const updated = await request(`/api/projects/${encodeURIComponent(activeProjectId)}/tasks/${encodeURIComponent(task.id)}`, {
          method: 'PATCH', headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ dueDate: dueDateInput.value })
        });
        task.dueDate = updated.dueDate || null;
        dueDateInput.value = task.dueDate || '';
        taskAlert.hidden = true;
        drawTasks();
      } catch (error) {
        taskAlert.textContent = error.message;
        taskAlert.hidden = false;
      }
    });
    dueDateForm.append(dueDateInput, saveDueDate);
    const destinationForm = document.createElement('form');
    destinationForm.className = 'task-move-form';
    const destination = document.createElement('select');
    destination.setAttribute('aria-label', 'Destination project');
    for (const project of activeProjects.filter(item => item.id !== activeProjectId)) {
      const option = document.createElement('option');
      option.value = project.id;
      option.textContent = project.name;
      destination.append(option);
    }
    const moveButton = document.createElement('button');
    moveButton.type = 'submit';
    moveButton.className = 'open-button';
    moveButton.textContent = 'Move task';
    destination.disabled = activeProjectArchived || destination.options.length === 0;
    moveButton.disabled = activeProjectArchived || destination.options.length === 0;
    destinationForm.addEventListener('submit', async event => {
      event.preventDefault();
      if (!destination.value) return;
      try {
        await request(`/api/projects/${encodeURIComponent(activeProjectId)}/tasks/${encodeURIComponent(task.id)}/move`, {
          method: 'POST', headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ destinationProjectId: destination.value })
        });
        currentTasks = currentTasks.filter(item => item.id !== task.id);
        drawTasks();
      } catch (error) {
        taskAlert.textContent = error.message;
        taskAlert.hidden = false;
      }
    });
    destinationForm.append(destination, moveButton);
    label.append(checkbox);
    row.append(title, renameForm, priority, dueDateForm, destinationForm, label);
    tasksNode.append(row);
  }
}

async function loadTasks() {
  if (!activeProjectId) return;
  const [tasks, projects] = await Promise.all([
    request(`/api/projects/${encodeURIComponent(activeProjectId)}/tasks`), request('/api/projects')
  ]);
  currentTasks = tasks;
  activeProjects = projects.filter(project => !project.archived);
  drawTasks();
}

async function renderRoute() {
  const match = location.pathname.match(/^\/projects\/([^/]+)$/);
  if (!match) {
    listView.hidden = false;
    detailView.hidden = true;
    await loadProjects();
    return;
  }
  try {
    const project = await request(`/api/projects/${encodeURIComponent(decodeURIComponent(match[1]))}`);
    document.querySelector('#detail-name').textContent = project.name;
    activeProjectId = project.id;
    taskFilter.value = 'All';
    priorityFilter.value = 'All';
    resetDueRange();
    setProjectArchived(project.archived);
    defaultPriority.value = project.defaultPriority || 'Normal';
    defaultPriority.dataset.saved = defaultPriority.value;
    listView.hidden = true;
    detailView.hidden = false;
    await loadTasks();
  } catch {
    activeProjectId = null;
    history.replaceState({}, '', '/');
    listView.hidden = false;
    detailView.hidden = true;
    await loadProjects();
  }
}

